import fs from 'node:fs';
const root = process.argv[2];
for (const name of ['data.json','text.txt','bytes.bin','missing.json','directory']) {
 const f=Bun.file(root+'/'+name); const out={name, size:f.size, lastModified:f.lastModified, type:f.type, ctor:f.constructor.name, tag:Object.prototype.toString.call(f)};
 for (const method of ['exists','text','json','arrayBuffer','bytes']) {
  try { const result=await f[method]();out[method]=result instanceof ArrayBuffer ? [...new Uint8Array(result)] : result instanceof Uint8Array ? [...result] : result; }
  catch(e) {out[method]={error:e.name,code:e.code,syscall:e.syscall,path:e.path};}
 }
 console.log(JSON.stringify(out));
}
const name=root+'/changing.txt';await Bun.write(name,'first');const f=Bun.file(name);const before={size:f.size,lastModified:f.lastModified};await Bun.write(name,'changed contents');console.log(JSON.stringify({changing:{before,after:{size:f.size,lastModified:f.lastModified,text:await f.text(),exists:await f.exists()},fresh:Bun.file(name).size}}));fs.unlinkSync(name);

import fs from 'node:fs';
const path = process.argv[2] + '/changing.txt';
const result=[];
for (const first of ['none','exists','text','arrayBuffer','size','lastModified']) {
 await Bun.write(path,'first'); const f=Bun.file(path);
 let before;
 if(first==='exists'||first==='text'||first==='arrayBuffer') before=await f[first]();
 else if(first!=='none') before=f[first];
 await Bun.write(path,'changed contents');
 const text=await f.text(); const size=f.size;fs.unlinkSync(path);
 let exists;try{exists=await f.exists()}catch(e){exists=e.code}
 let afterDelete;try{afterDelete=await f.text()}catch(e){afterDelete=e.code}
 result.push({first,before:before instanceof ArrayBuffer?before.byteLength:before,text,size,exists,afterDelete});
}
console.log(JSON.stringify(result));
